#include <iostream>
#include <vector>

bool isPalindrome(const std::vector<int>& items) {
    int left = 0;
    int right = static_cast<int>(items.size()) - 1;
    while (left < right) {
        if (items[left] != items[right]) {
            return false;
        }
        left++;
        right--;
    }
    return true;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> items(n);
    for (int i = 0; i < n; i++) {
        std::cin >> items[i];
    }
    std::cout << std::boolalpha << isPalindrome(items) << "\n";
    return 0;
}

