package main

import "fmt"

func isPalindrome(items []int) bool {
	left := 0
	right := len(items) - 1
	for left < right {
		if items[left] != items[right] {
			return false
		}
		left++
		right--
	}
	return true
}

func main() {
	var n int
	fmt.Scan(&n)
	items := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&items[i])
	}
	fmt.Println(isPalindrome(items))
}
